function max_error = check_actor(filename)
% Optional MATLAB check; stored references were generated by SB3 in Python.
actor = load(filename);
reference = actor.validation_actions_rows;
actual = zeros(size(reference), 'single');
for k = 1:size(reference, 1)
    actual(k,:) = ppo_actor_predict(actor, actor.validation_observations_rows(k,:)')';
end
max_error = max(abs(actual-reference), [], 'all');
assert(max_error < 2e-5, 'Exported actor disagrees with Python');
end
